css:
.bs-stage { position: relative; border: 2px solid var(--ink); border-radius: 12px; overflow: hidden; background: #d6cfbd; }
.bs-stage canvas { touch-action: none; cursor: grab; user-select: none; -webkit-user-select: none; }
.bs-stage canvas.holding { cursor: grabbing; }
.bs-out { margin: 0; font-size: 21px; line-height: 1.5; background: #fffbe6; border: 2px solid var(--accent); border-radius: 12px; padding: 10px 14px; min-height: 4.6em; flex: none; }
.bs-facts { display: grid; grid-template-columns: auto 1fr; gap: 6px 14px; margin: 0; font-size: 20px; line-height: 1.4; }
.bs-facts dt { font-weight: 800; color: var(--accent); white-space: nowrap; }
.bs-facts dd { margin: 0; }
section.ex.u-done .bs-facts { display: none; }

